 function quarter(s){const a=ensure(s),q=s.calendar.count;if(!s.accepted||s.dead||a.lastQuarter===q)return;a.lastQuarter=q;if(a.offerQuarter!==q)s.seen=s.seen.filter(id=>id!=='adventure-contract-offer');if(isCareer(s))a.member=true;const y=WorldTimeline.year(s);if(a.member&&Engine.biological(s)>=16&&a.lastYear!==y){a.lastYear=y;if(RaceDrives.cashless(s))s.raceDrives.resource=Math.max(0,s.raceDrives.resource-2);else{const due=120,paid=Math.min(s.gold,due);s.gold=round(s.gold-paid);if(paid<due){Economy.ensure(s).debt=Math.min(1e9,Economy.ensure(s).debt+due-paid);Economy.record(s,'shortfall',due-paid)}Economy.record(s,'otherSpend',due)}}}
