 function valid(s){const a=s.adventure;if(a===undefined)return true;const n=(v,max=100000)=>Number.isInteger(v)&&v>=0&&v<=max,q=v=>Number.isInteger(v)&&v>=-1&&v<=(s.calendar?.count??0);return a&&a.version===1&&typeof a.member==='boolean'&&n(a.xp)&&n(a.rank,7)&&thresholds[a.rank]<=a.xp&&n(a.completed)&&n(a.failed)&&n(a.serial)&&q(a.lastQuarter)&&q(a.lastReturn)&&q(a.trainingQuarter)&&(a.offerQuarter===undefined||q(a.offerQuarter))&&(a.lastStoryQuarter===undefined||q(a.lastStoryQuarter))&&Number.isInteger(a.lastYear)&&a.lastYear>=-1&&a.lastYear<=WorldTimeline.year(s)&&a.gear&&['weapon','ward','kit'].every(k=>n(a.gear[k],3))&&Number.isFinite(a.gear.condition)&&a.gear.condition>=0&&a.gear.condition<=100&&Array.isArray(a.history)&&a.history.length<=24&&a.history.every(h=>h&&Number.isFinite(h.age)&&h.age>=0&&h.age<=s.age&&Number.isInteger(h.year)&&h.year>=1000&&h.year<=WorldTimeline.year(s)&&typeof h.text==='string'&&h.text.length<=400)&&(a.active===null||a.active&&get(a.active.id)&&n(a.active.stage,2)&&q(a.active.started)&&Number.isInteger(a.active.ready)&&a.active.ready>=a.active.started&&a.active.ready<=(s.calendar?.count??0)+1&&[null,'careful','talk','force'].includes(a.active.route)&&typeof a.active.victory==='boolean'&&typeof a.active.advance==='boolean'&&typeof a.active.native==='boolean'&&[null,'peace','evidence','clear'].includes(a.active.returnKind))}
